#include <print>
#include <memory>
#include <utility>

struct Node {
    int value;
    std::unique_ptr<Node> left;
    std::unique_ptr<Node> right;
};

void inorder(const Node* p) {
    if (p == nullptr) return;
    inorder(p->left.get());
    std::print("{} ", p->value);
    inorder(p->right.get());
}

void preorder(const Node* p) {
    if (p == nullptr) return;
    std::print("{} ", p->value);
    preorder(p->left.get());
    preorder(p->right.get());
}

void postorder(const Node* p) {
    if (p == nullptr) return;
    postorder(p->left.get());
    postorder(p->right.get());
    std::print("{} ", p->value);
}

int main() {
    auto head = std::make_unique<Node>();
    head->value = 4;
    head->left = std::make_unique<Node>();
    head->left->value = 2;
    head->right = std::make_unique<Node>();
    head->right->value = 6;
    const Node* root = head.get();

    std::print("中序: "); inorder(root); std::println("");
    std::print("前序: "); preorder(root); std::println("");
    std::print("后序: "); postorder(root); std::println("");
    // 前序 4 2 6，中序 2 4 6，后序 2 6 4
    return 0;
}

